<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {captureToolWindow,captureToolCapabilities} from './capture-tools-state.js';
 import {screenshotMenus} from './capture-tools-menus.js';
 import {createCaptureToolNativeView} from './capture-tools-native-view.js';
 import './capture-tools.css';
 let {state: screenshotState,profile,windowId,window:actualWindow=null,execute,registerView,available=true,active=true,controls={},getShared=null}=$props();
 let root=$state(null),message=$state(''),selecting=$state(false),drag=$state(null),choices=$state([]),busy=$state(false),stroke=$state(null);let originalState,originalProfile,originalId,facade,retired=false,strokeImage,strokeRevision;
 const id=$derived(windowId??actualWindow?.id),session=$derived(captureToolWindow(screenshotState,id)),cap=$derived(captureToolCapabilities(profile,'screenshot')),groups=$derived(screenshotMenus({state: screenshotState,profile,windowId:id})),menu=$derived(groups.find(g=>g.id===session?.menu));
 const modes=$derived([['screen',cap.highSierra?'Screen':cap.windows?'Full screen':'Capture Entire Screen'],['window',cap.windows?'Window':'Capture Selected Window'],['region',cap.highSierra?'Selection':cap.windows?'Rectangle':'Capture Selected Portion']]);
 const imageSize=$derived({width:session?.edit.crop?.width??session?.image?.width??480,height:session?.edit.crop?.height??session?.image?.height??280});
 function current(){return !retired&&root?.isConnected&&screenshotState===originalState&&profile===originalProfile&&id===originalId;}
 async function command(suffix,payload={}){if(!current()||!available||!active)return;const node=root,r=await execute(`screenshot.${suffix}`,{windowId:id},payload);if(current()&&root===node)message=r?.status==='applied'?'':r?.error?.message??'The original capture is unavailable.';return r;}
 async function capture(preview=false){if(busy)return;busy=true;try{await command(preview?'preview':'capture');}finally{if(current())busy=false;}}
 async function chooseMode(mode){const result=await command('settings',{mode});if(current()&&result?.status==='applied')choices=facade.windowChoices();}
 function beginSelection(){if(!current()||!available||!active||busy)return;selecting=true;drag=null;message='Drag across the actual simulated desktop. Escape cancels.';}
 $effect(()=>{if(!available||!active||screenshotState!==originalState||profile!==originalProfile||id!==originalId){selecting=false;drag=null;stroke=null;facade?.selectionRect(null);facade?.cancelCapture();}});
 function pointerDown(event){if(event.button!==0||!selecting||!current()||!facade.containsPoint({x:event.clientX,y:event.clientY}))return;event.preventDefault();event.stopPropagation();drag={pointerId:event.pointerId,x:event.clientX,y:event.clientY,endX:event.clientX,endY:event.clientY};}
 function pointerMove(event){if(selecting&&drag&&drag.pointerId===event.pointerId&&current()){drag={...drag,endX:event.clientX,endY:event.clientY};facade.selectionRect({x:Math.min(drag.x,drag.endX),y:Math.min(drag.y,drag.endY),width:Math.abs(drag.endX-drag.x),height:Math.abs(drag.endY-drag.y)},()=>current()&&available&&active);}}
 async function pointerUp(event){if(!selecting||!drag||drag.pointerId!==event.pointerId||!current())return;event.preventDefault();event.stopPropagation();const r={x:Math.min(drag.x,event.clientX),y:Math.min(drag.y,event.clientY),width:Math.abs(event.clientX-drag.x),height:Math.abs(event.clientY-drag.y)};selecting=false;drag=null;facade.selectionRect(null);if(r.width<1||r.height<1){message='Drag a nonempty selection.';return;}const changed=await command('select',{region:r});if(changed?.status==='applied'&&current()){await command('settings',{mode:'region'});if(current())capture(true);}}
 function numeric(key,value){const region=session.region??facade.sceneBounds();if(region)command('select',{region:{...region,[key]:Number(value)}});}
 function imagePoint(event){const node=event.currentTarget,r=node.getBoundingClientRect();return {x:Math.max(0,Math.min(imageSize.width,Math.round((event.clientX-r.x)*imageSize.width/r.width))),y:Math.max(0,Math.min(imageSize.height,Math.round((event.clientY-r.y)*imageSize.height/r.height)))};}
 function imageBegin(event){if(!current()||!available||!active||selecting||busy||!session.image||event.button!==0||session.sheet||stroke)return;event.preventDefault();event.currentTarget.setPointerCapture(event.pointerId);const point=imagePoint(event);strokeImage=session.image;strokeRevision=session.revision;stroke={pointerId:event.pointerId,tool:session.tool,color:session.color,size:session.tool==='highlight'?20:3,points:[point,point]};}
 function imageMove(event){if(!stroke||stroke.pointerId!==event.pointerId||!current()||session.image!==strokeImage||session.revision!==strokeRevision)return;const point=imagePoint(event);if(stroke.tool==='crop')stroke={...stroke,points:[stroke.points[0],point]};else if(stroke.points.length<2048)stroke={...stroke,points:[...stroke.points,point]};}
 function imageEnd(event){if(!stroke||stroke.pointerId!==event.pointerId)return;const authored=stroke;stroke=null;if(!current()||session.image!==strokeImage||session.revision!==strokeRevision)return;if(authored.tool==='crop'){const [a,b]=authored.points,rect={x:Math.min(a.x,b.x),y:Math.min(a.y,b.y),width:Math.abs(a.x-b.x),height:Math.abs(a.y-b.y)};if(rect.width&&rect.height)command('crop',{rect});}else command('annotate',{stroke:{tool:authored.tool,color:authored.color,size:authored.size,points:authored.points}});}
 async function menuAction(item){if(!item.enabled)return;const r=await command(item.request.command.slice(11),item.request.payload);if(current()&&r?.status==='applied'&&session.menu)command('sheet',{menu:null});}
 function keyboard(event){if(!current()||!available||!active)return;if(event.key==='Escape'){selecting=false;drag=null;stroke=null;facade.selectionRect(null);facade.cancelCapture();if(session.sheet||session.menu)command('sheet',{sheet:null,menu:null});return;}if(event.target.matches('input,select,textarea'))return;if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='z'){event.preventDefault();command('undo');return;}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='s'){event.preventDefault();command('sheet',{sheet:'save'});return;}if(event.key==='Enter'){event.preventDefault();capture();}if(event.metaKey&&event.shiftKey&&['3','4'].includes(event.key)){event.preventDefault();command('settings',{mode:event.key==='3'?'screen':'region',destination:event.ctrlKey?'clipboard':session.destination}).then(r=>{if(current()&&r?.status==='applied'){if(event.key==='4')beginSelection();else capture();}});}}
 onMount(()=>{originalState=screenshotState;originalProfile=profile;originalId=id;facade=createCaptureToolNativeView({getRoot:()=>root,getState:()=>screenshotState,getProfile:()=>profile,windowId:id,available:()=>current()&&available&&active,tick,getShared:getShared??controls.getShared});registerView?.(id,facade);choices=facade.windowChoices();if(session.image)facade.restoreImage(()=>current()&&available&&active);const doc=root.ownerDocument;doc.addEventListener('pointerdown',pointerDown,true);doc.addEventListener('pointermove',pointerMove);doc.addEventListener('pointerup',pointerUp,true);doc.addEventListener('keydown',keyboard);return()=>{retired=true;doc.removeEventListener('pointerdown',pointerDown,true);doc.removeEventListener('pointermove',pointerMove);doc.removeEventListener('pointerup',pointerUp,true);doc.removeEventListener('keydown',keyboard);facade.destroy();registerView?.(originalId,null,facade);};});
</script>
<section bind:this={root} class="capture-tool screenshot-tool" class:classic={cap.classic} class:windows={cap.windows} class:golden={cap.golden} class:inactive={!active} data-capture-window={id} data-profile={profile.id} aria-label={cap.label} role="region" tabindex="0">
 {#if session}
 <header class="capture-title">{#if !cap.windows}<WindowControls {active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} fullScreen={controls.fullScreen}/>{/if}<strong>{cap.label}</strong>{#if cap.windows}<button aria-label="Close Snipping Tool" data-capture-control="close" onclick={()=>command('window.close')}>×</button>{/if}</header>
 <div class="capture-body" inert={!available||!active||!!session.sheet}>
 <nav class="capture-menus" aria-label="Capture menus">{#each groups.filter(g=>g.id!=='app') as group}<button data-capture-control={`menu:${group.id}`} aria-expanded={menu?.id===group.id} onclick={()=>command('sheet',{menu:menu?.id===group.id?null:group.id})}>{group.label}</button>{/each}</nav>
 {#if menu}<div class="capture-menu" role="menu">{#each menu.children as item}<button role="menuitem" data-capture-control={item.id} disabled={!item.enabled} onclick={()=>menuAction(item)}><span>{item.checked?'✓ ':''}{item.label}</span><kbd>{item.shortcut??''}</kbd></button>{/each}</div>{/if}
 <div class="capture-toolbar" class:modern={!cap.classic}>{#each modes as [mode,label]}<button data-capture-control={`mode:${mode}`} aria-pressed={session.mode===mode} onclick={()=>chooseMode(mode)}><span class={`capture-symbol ${mode}`} aria-hidden="true"></span>{label}</button>{/each}<button data-capture-control="options" onclick={()=>command('sheet',{sheet:'preferences'})}>{cap.windows?'…':'Options'}</button></div>
 <div class="capture-selection-controls">{#if session.mode==='window'}<label>Window <select data-capture-control="selectedWindow" value={session.selectedWindowId??''} onfocus={()=>choices=facade.windowChoices()} onchange={e=>command('select',{selectedWindowId:e.currentTarget.value||null})}><option value="">Choose an actual window</option>{#each choices as row}<option value={row.id}>{row.label}</option>{/each}</select></label>{:else if session.mode==='region'}<button data-capture-control="selectRegion" onclick={beginSelection}>{selecting?'Drag in desktop…':'Select Region'}</button>{#each ['x','y','width','height'] as key}<label class="capture-coordinate">{key}<input type="number" data-capture-control={`region:${key}`} value={session.region?.[key]??''} min={key==='width'||key==='height'?1:-100000} max="100000" onchange={e=>numeric(key,e.currentTarget.value)}/></label>{/each}{/if}</div>
 {#if session.image}<div class="capture-editor-toolbar"><span>Edit captured PNG</span>{#each ['pen','highlight','crop'] as tool}<button data-capture-control={`tool:${tool}`} aria-pressed={session.tool===tool} onclick={()=>command('settings',{tool})}>{tool==='highlight'?'Highlighter':tool==='crop'?'Crop':'Pen'}</button>{/each}<input data-capture-control="color" type="color" aria-label="Annotation color" value={session.color} onchange={e=>command('settings',{color:e.currentTarget.value})}/><button data-capture-control="undo" disabled={!session.undo.length||!!stroke} onclick={()=>command('undo')}>Undo</button><button data-capture-control="saveAs" onclick={()=>command('sheet',{sheet:'save'})}>Save As…</button><button data-capture-control="copy" onclick={()=>command('copy')}>Copy</button><button data-capture-control="share" onclick={()=>command('share')}>Share</button></div>{/if}
 <div class="capture-preview" class:editing={!!session.image}><canvas width="480" height="280" data-capture-preview data-capture-control="image" aria-label="Genuine selected desktop pixel preview; drag to annotate or crop" onpointerdown={imageBegin} onpointermove={imageMove} onpointerup={imageEnd} onpointercancel={()=>stroke=null} onlostpointercapture={()=>stroke=null}></canvas>{#if stroke}<svg class="capture-stroke-preview" viewBox={`0 0 ${imageSize.width} ${imageSize.height}`} aria-hidden="true">{#if stroke.tool==='crop'}<rect x={Math.min(stroke.points[0].x,stroke.points[1].x)} y={Math.min(stroke.points[0].y,stroke.points[1].y)} width={Math.abs(stroke.points[0].x-stroke.points[1].x)} height={Math.abs(stroke.points[0].y-stroke.points[1].y)} fill="none" stroke="white" stroke-width="2" stroke-dasharray="5 3"/>{:else}<polyline points={stroke.points.map(p=>`${p.x},${p.y}`).join(' ')} fill="none" stroke={stroke.color} stroke-width={stroke.size} stroke-linecap="round" opacity={stroke.tool==='highlight'?0.35:1}/>{/if}</svg>{/if}{#if !session.image}<div class="capture-empty"><span aria-hidden="true">⌗</span><p>Select a scene region, window or entire desktop,<br/>then preview the actual pixels.</p></div>{/if}</div>
 {#if drag}<p role="status">Selection: {Math.round(Math.min(drag.x,drag.endX))}, {Math.round(Math.min(drag.y,drag.endY))} · {Math.round(Math.abs(drag.endX-drag.x))} × {Math.round(Math.abs(drag.endY-drag.y))}</p>{/if}
 <footer class="capture-actions"><span>{session.image?`${imageSize.width} × ${imageSize.height} pixels`:'No captured pixels'}</span><button data-capture-control="preview" disabled={busy||selecting} onclick={()=>capture(true)}>Preview</button><button class="capture-primary" data-capture-control="capture" disabled={busy||selecting} onclick={()=>capture(cap.windows)}>{busy?'Capturing…':cap.windows?'New snip':'Capture'}</button></footer>
 <output data-capture-countdown aria-live="polite"></output><p class="capture-status" role="status">{message||session.status}</p><p class="capture-qualification">{cap.qualification}</p>
 </div>
 {#if session.sheet==='save'}<div class="capture-sheet" role="dialog" aria-modal="true" aria-label="Save captured PNG"><h2>Save As</h2><p>Save the exact captured pixels, crop and authored pen/highlighter annotations as a genuine PNG File.</p><label>File name <input data-capture-control="save:name" value={session.saveName} placeholder="Authored date and time.png" onchange={e=>command('settings',{saveName:e.currentTarget.value})}/></label><label>Destination folder ID <input data-capture-control="save:parent" value={session.parentId} onchange={e=>command('settings',{parentId:e.currentTarget.value})}/></label><div class="capture-dialog-actions"><button data-capture-control="save:cancel" onclick={()=>command('sheet',{sheet:null})}>Cancel</button><button class="capture-primary" data-capture-control="save:confirm" onclick={()=>command('save')}>Save PNG</button></div><p class="capture-status" role="status">{message}</p></div>{/if}
 {#if session.sheet&&session.sheet!=='save'}<div class="capture-sheet" role="dialog" aria-modal="true" aria-label={session.sheet==='help'?cap.label+' Help':'Capture Options'}><h2>{session.sheet==='help'?cap.label+' Help':'Capture Options'}</h2>{#if session.sheet==='preferences'}<label>Save to <select data-capture-control="destination" value={session.destination} onchange={e=>command('settings',{destination:e.currentTarget.value})}><option value="file">Actual scene PNG File</option><option value="clipboard">Scene image clipboard</option></select></label><label>Destination folder ID <input data-capture-control="parentId" value={session.parentId} onchange={e=>command('settings',{parentId:e.currentTarget.value})}/></label><label>Timer <select data-capture-control="delay" value={session.delay} onchange={e=>command('settings',{delay:Number(e.currentTarget.value)})}>{#each [0,5,10] as value}<option {value}>{value?`${value} seconds`:'None'}</option>{/each}</select></label><label>Date format <select data-capture-control="dateFormat" value={session.dateFormat} onchange={e=>command('settings',{dateFormat:e.currentTarget.value})}><option value="native">Screen Shot date and time</option><option value="iso">ISO 8601</option></select></label>{/if}<p>Capture uses only genuine simulated desktop DOM. Region values are client coordinates mapped through original capture bounds and imageRect. Preview retains canonical actual PNG bytes; pen, highlighter, crop and undo modify authored edits over those pixels. Save As, image copy and PNG sharing use actual Root destinations.</p><p>Drag to select; Escape cancels a selection or timer. Enter captures. On Mac, Shift–Command–3 selects the screen and Shift–Command–4 a region; adding Control copies to the scene clipboard. Command/Control–Z undoes an edit; Command/Control–S opens Save As. File names use authored scene time, never host time.</p><p>{cap.qualification}</p><button data-capture-control="sheet:done" onclick={()=>command('sheet',{sheet:null})}>Done</button></div>{/if}
 {:else}<p role="alert">The original Screenshot scene window is unavailable.</p>{/if}
</section>
